mapper.select:
SELECT o.order_id, o.record_id, o.pet_id, o.client_id, o.doctor_id, o.item_id, o.item_name, o.group_name, o.fee, o.exam_part, o.result, o.report_time, o.status, o.note, o.create_time, p.pet_name, c.client_name, d.doctor_name, r.diagnosis FROM image_order o LEFT JOIN pet p ON o.pet_id = p.pet_id LEFT JOIN client c ON o.client_id = c.client_id LEFT JOIN doctor d ON o.doctor_id = d.doctor_id LEFT JOIN medical_record r ON o.record_id = r.record_id WHERE o.is_del = 0
AND o.status = #{status}
ORDER BY o.status ASC, o.create_time DESC
